package com.wykh4hn.assigment_2.model

import android.os.Parcelable
import androidx.annotation.DrawableRes
import kotlinx.parcelize.Parcelize

/**
 * One car the company can rent. The data lives in memory only (see CarData).
 *
 * Parcelable (generated by @Parcelize, Week 6) so a whole Car object
 * can travel inside an Intent from MainActivity to BookingActivity.
 *
 * @property id unique number, used to track rented and favourite cars without editing the base list
 * @property name maker, e.g. "Toyota"
 * @property model model name, e.g. "Corolla"
 * @property year model year
 * @property rating average rating from 1.0 to 5.0
 * @property kilometres odometer reading in km
 * @property dailyCost price per day, in credits
 * @property category short line shown above the name, e.g. "Sedan · 5 seats"
 * @property imageRes drawable resource of the car photo
 */
@Parcelize
data class Car(
    val id: Int,
    val name: String,
    val model: String,
    val year: Int,
    val rating: Float,
    val kilometres: Int,
    val dailyCost: Int,
    val category: String,
    @DrawableRes val imageRes: Int
) : Parcelable {

    /** Maker and model together, e.g. "Toyota Corolla". */
    val fullName: String
        get() = "$name $model"
}